function CommonHostingDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(
        util.cs_generator(
            function()
                self.isHost = true
                self.controller:SetSortOrder(15)
                UIEventProxy.Create(self.RT_Bg.gameObject).onPointerClick = function()
                    print("点击关闭托管界面")
                    -- 发送取消托管消息
                    BattleViewMgr.netMgr:Send(BattleViewMgr.netMgr.SendPackageIds.RequestHosting, {isOpen = 0})
                    -- 打开网络消息遮罩
                    GameUtils.BeforeRequest()
                    -- 等待网络消息返回
                end
                self.eventOnReceivePackage = Events.AddListener(Constants.EventNames.BattleReceiveOnlineSettlement, Bind(self, self.OnBattleEnd))
                self.eventOnReceivePackage = Events.AddListener(Constants.EventNames.BattleNetworkOnReceived, Bind(self, self.OnReceivedPackage))
            end
        )
    )
    return coWait
end

function CommonHostingDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(
        util.cs_generator(
            function()
                print("托管界面终结")
                if self.isHost then
                    BattleViewMgr.netMgr:Send(BattleViewMgr.netMgr.SendPackageIds.RequestHosting, {isOpen = 0})
                end
                print("->CommonHostingDialog:OnFinalize")
                Events.RemoveListener(Constants.EventNames.BattleInputFinished, self.eventOnReceivePackage)
                Events.RemoveListener(Constants.EventNames.BattleReceiveOnlineSettlement, self.OnBattleEnd)

                self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
                self:Delete()
                self = nil --lua层的gc需要
            end
        )
    )
    return coWait
end

------------ lifeCycle ------------

function CommonHostingDialog:OnReceivedPackage(packageId, packageData)
    if not UIBattlingTools.IsMyPlayerId(packageData.playerId) then return end

    local ReceivePackageIds = BattleViewMgr.netMgr.ReceivePackageIds
    if packageId == ReceivePackageIds.PlayerHosting then
        if packageData.isOpen == 0 then
            self:ExitHosting()
        end
    end
end

function CommonHostingDialog:OnBattleEnd()
    self:ExitHosting()
end

function CommonHostingDialog:ExitHosting()
    -- 关闭托管界面和消息遮罩
    self.isHost = false
    GameUtils.AfterRequest()
    UIModule.CloseDialog(self.controller)
    -- CS.UnityEngine.GameObject.Destroy(self.controller.gameObject)
end

return CommonHostingDialog